<?php require_once dirname(__DIR__).'/lib.php';admin_required();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM contracts WHERE id=?');$s->execute([$id]);$c=$s->fetch();if(!$c||$c['status']!=='completed')die('최종 확정된 계약서가 아닙니다.');?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/app.css"><title>최종 PDF</title><script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script></head><body><main class="wrap"><div class="card no-print"><h1>최종 PDF 생성 및 발송</h1><p>아래 버튼을 누르면 계약서를 PDF로 만들어 서버에 저장합니다. 이후 임차인에게 안전한 다운로드 링크를 문자로 보낼 수 있습니다.</p><div class="actions"><button class="btn big green" id="make">PDF 생성·저장</button><button class="btn" id="send" disabled>임차인에게 PDF 링크 문자</button><a class="btn gray" href="view.php?id=<?=$id?>">돌아가기</a></div><div id="msg" class="alert" style="display:none"></div></div><?=render_contract($c)?></main><script>const id=<?=$id?>,msg=document.getElementById('msg'),send=document.getElementById('send');document.getElementById('make').onclick=async()=>{msg.style.display='block';msg.className='alert warn';msg.textContent='PDF를 생성하고 있습니다.';const opt={margin:8,filename:'lease_'+id+'.pdf',image:{type:'jpeg',quality:.96},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},pagebreak:{mode:['css','legacy']}};const blob=await html2pdf().set(opt).from(document.getElementById('contractDocument')).outputPdf('blob');const fd=new FormData();fd.append('id',id);fd.append('pdf',blob,'lease_'+id+'.pdf');const r=await fetch('../api/upload_pdf.php',{method:'POST',body:fd});const j=await r.json();msg.className=j.ok?'alert ok':'alert err';msg.textContent=j.message;if(j.ok){send.disabled=false;send.dataset.url=j.url}};send.onclick=async()=>{const fd=new FormData();fd.append('id',id);const r=await fetch('../api/send_final.php',{method:'POST',body:fd});const j=await r.json();msg.style.display='block';msg.className=j.ok?'alert ok':'alert err';msg.textContent=j.message};</script></body></html>